    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        List<String> tok = new ArrayList<>();
        String line;
        while ((line = br.readLine()) != null) {
            StringTokenizer st = new StringTokenizer(line);
            while (st.hasMoreTokens()) tok.add(st.nextToken());
        }
        int n = Integer.parseInt(tok.get(0));
        String[] words = tok.subList(1, 1 + n).toArray(new String[0]);
        List<List<String>> groups = new ArrayList<>();
        for (List<String> g : groupAnagrams(words)) {
            List<String> copy = new ArrayList<>(g);
            Collections.sort(copy);
            groups.add(copy);
        }
        groups.sort((a, b) -> a.get(0).compareTo(b.get(0)));
        StringBuilder sb = new StringBuilder();
        sb.append(groups.size()).append('\n');
        for (List<String> g : groups) sb.append(String.join(" ", g)).append('\n');
        System.out.print(sb);
    }
}
